/* HFY-TSK-064: offline shell only. Registered by the shellV2 island at /sw.js?v=<sha8 of this file>; scope "/". Serve with Cache-Control: no-cache. */
// Asset versions (islands/build.mjs, assets.mjs): Cloudflare caches static files for 4 h under the URL they were fetched at and
// CloudFront invalidations never reach it, so every URL this worker caches or precaches carries ?v=<sha8 of the file>, the same
// value the pages and the island loader use. The block below is stamped by the build from the built files; do not edit it.
/* hfy-asset-versions:start (content hashes of the files this script loads: generated by islands/build.mjs, do not edit) */
const ASSET_V = {
  "theme": "f103422b",
  "manifest": "c0f9b5fc",
  "shell": {
    "js": "f308fe0b",
    "css": "6aa10a05"
  },
  "notify": "9a3183f2"
};
/* hfy-asset-versions:end */
// HFY-R58: the cache name comes from the ?v this worker is registered at (the hash of this file, which embeds the hashes above), so
// every change to the strategy or to the precached files starts a new cache; activate drops every other cache (incl. stale shell.js).
// A registration without a valid ?v (a bare /sw.js) gets the "dev" cache, which the same rule keeps from outliving a versioned one.
// v3 (design-system pass): the theme layer /css/hfy-theme.css (network-first, offline from any cached ?v) and the self-hosted
// faces under /fonts/ (content-hashed names: cache-first).
const REGISTERED_V = new URL(self.location.href).searchParams.get("v") || "";
const VERSION = "hfy-shell-" + (/^[0-9a-f]{8}$/.test(REGISTERED_V) ? REGISTERED_V : "dev");
const versioned = (path, version) => (version ? path + "?v=" + version : path);
const THEME = "/css/hfy-theme.css";
const SHELL = ASSET_V.shell || {};
// Versioned URLs, exactly as the pages request them, so the precached copies are the ones served offline.
const PRECACHE = [
  "/offline.html",
  versioned(THEME, ASSET_V.theme),
  versioned("/js/islands/shell.js", SHELL.js),
  versioned("/js/islands/shell.css", SHELL.css),
  versioned("/manifest.webmanifest", ASSET_V.manifest),
  "/images/pwa-192.png"
];
// Stable names (the file at the URL changes with a deploy): network-first, one cached copy per path.
const STABLE = new Set(PRECACHE.map((u) => new URL(u, self.location.origin).pathname));
const ISLANDS = "/js/islands/";
const CHUNKS = "/js/islands/chunks/";
const FONTS = "/fonts/";

// HFY-TSK-068: @io-kit/notify's notify-sw (push + notificationclick deep links) is copied to /js/islands/ by islands/build.mjs.
try { importScripts(versioned("/js/islands/notify-sw.js", ASSET_V.notify)); } catch (e) { /* not shipped yet */ }

self.addEventListener("install", (event) => {
  // skipWaiting: a deploy replaces the previous worker (and, on activate, its caches) at once instead of when the last tab closes.
  event.waitUntil(
    caches.open(VERSION)
      .then((c) => Promise.all(PRECACHE.map((u) => c.add(new Request(u, { cache: "reload" })).catch(() => {}))))
      .then(() => self.skipWaiting())
  );
});
self.addEventListener("activate", (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("message", (event) => { if (event.data === "SKIP_WAITING" || (event.data && event.data.type === "SKIP_WAITING")) self.skipWaiting(); });

// Clone synchronously, before the response is handed to respondWith (whose body the browser then consumes);
// the cache write is kept alive with waitUntil.
function fetchAndStore(event, req) {
  return fetch(req).then((res) => {
    if (res.ok && res.status === 200 && res.type === "basic") {
      const copy = res.clone();
      event.waitUntil(caches.open(VERSION).then((c) => c.put(req, copy)).catch(() => {}));
    }
    return res;
  });
}

// Stable names are requested as <path>?v=<sha8>: keep only the newest copy of each path (whatever its ?v) for offline use.
function fetchLatest(event, req) {
  return fetch(req).then((res) => {
    if (res.ok && res.status === 200 && res.type === "basic") {
      const copy = res.clone();
      const path = new URL(req.url).pathname;
      event.waitUntil(
        caches.open(VERSION).then((c) =>
          c.keys()
            .then((keys) => Promise.all(keys.filter((k) => new URL(k.url).pathname === path && k.url !== req.url).map((k) => c.delete(k))))
            .then(() => c.put(req, copy))
        ).catch(() => {})
      );
    }
    return res;
  });
}
// Offline: the cached copy of exactly this URL, else the newest copy of the path under any ?v.
const offlineCopy = (req) => caches.match(req).then((hit) => hit || caches.match(req, { ignoreSearch: true })).then((hit) => hit || Response.error());

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  // HFY-TSK-142: /chat/ws and /chat/v1/ belong to the chat Worker (a route ahead of CloudFront). They are network-only, never touched here;
  // /chat/ itself (the page) is an ordinary navigation. A WebSocket never reaches a service worker, so this guards the HTTP routes.
  if (url.origin !== location.origin || /^\/(auth|api)(\/|$)/.test(url.pathname) || /^\/chat\/(ws|v1)(\/|$)/.test(url.pathname)) return;
  if (req.mode === "navigate") {
    event.respondWith(fetch(req).catch(() => caches.match("/offline.html")));
    return;
  }
  // Content-hashed chunks and font files never change under a URL: cache-first, stored on first use so the shell works offline.
  if (url.pathname.startsWith(CHUNKS) || url.pathname.startsWith(FONTS)) {
    event.respondWith(caches.match(req).then((hit) => hit || fetchAndStore(event, req)));
    return;
  }
  // The theme layer, the island entries (<name>.js / <name>.css), the manifest and the other stable names: network-first (a deploy
  // changes them under the same path, and a request carries the new ?v), so the entry module always matches the chunk hashes that
  // are actually on the server; the cached copy is only the offline fallback.
  if (STABLE.has(url.pathname) || url.pathname.startsWith(ISLANDS)) {
    event.respondWith(fetchLatest(event, req).catch(() => offlineCopy(req)));
  }
});
